const CACHE="recipes-react-shell-v1";const BASE="/recipe-pwa/react/";const FILES=[BASE,BASE+"index.html",BASE+"manifest.webmanifest"];self.addEventListener("install",event=>{event.waitUntil(caches.open(CACHE).then(cache=>Promise.all(FILES.map(f=>cache.add(f).catch(()=>{})))));self.skipWaiting()});self.addEventListener("activate",event=>{event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith("recipes-react-shell-")&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim()))});self.addEventListener("fetch",event=>{const req=event.request;if(req.method!=="GET"||new URL(req.url).origin!==location.origin)return;event.respondWith((async()=>{try{const response=await fetch(req);if(response.ok){const cache=await caches.open(CACHE);cache.put(req,response.clone())}return response}catch{const cache=await caches.open(CACHE);return await cache.match(req)||await cache.match(BASE+"index.html")||Response.error()}})())});